task.dot:
digraph task {
    rankdir=LR;
    node [shape=circle];
    "TODO" -> "IN_PROGRESS" [label="START"];
    "IN_PROGRESS" -> "PENDING_VERIFY" [label="SUBMIT"];
    "PENDING_VERIFY" -> "DONE" [label="PASS / a:taskPassAction / g:verifyResultGuard"];
    "PENDING_VERIFY" -> "IN_PROGRESS" [label="REJECT / g:verifyResultGuard"];
    "DONE" [shape=doublecircle];
}
